class Holder:
    """Register, rotate, revoke and inspect credentials by name in the receiving
    account. Same-account identity alone grants nothing; each call is a rights
    decision on the bound receiving subject. No call returns secret bytes, and
    metadata derives nothing from them. An absent policy service reads
    unavailable. An unconfigured platform store or a machine-scope runtime reads
    no_secure_store; the provider substitutes no environment, file or
    configuration source."""

    def store(self, expected_revision: str, registration: Registration) -> StoreResult:
        """Conditionally register one secret for the receiving account. Gated by
        abstraction.credentials/holder.manage on resource account for the bound
        receiving subject; authorization precedes every store effect. The secret
        leaves the request only into the configured platform store. Returns
        stored, conflict, invalid, unsupported_kind, no_secure_store, exhausted,
        forbidden or unavailable."""
        raise NotImplementedError

    def rotate(self, expected_revision: str, rotation: Rotation) -> RotateResult:
        """Conditionally replace the bytes of an existing record and its expiry;
        kind and scope are unchanged. Gated by holder.manage."""
        raise NotImplementedError

    def revoke(self, expected_revision: str, name: str) -> RevokeResult:
        """Conditionally destroy the bytes and tombstone the record. Gated by
        holder.manage. A failed or uncertain reply claims no destruction;
        inspect List before another intent."""
        raise NotImplementedError

    def list(self, cursor: str, limit: int) -> MetadataPage:
        """Read the receiving account's records and the provider limits. Gated by
        abstraction.credentials/holder.read on resource account; every
        continuation rechecks. limit is 1..64."""
        raise NotImplementedError

    def audit(self, cursor: str, max_entries: int) -> AuditPage:
        """Read the receiving account's retained credential events. Gated by
        holder.read. Empty cursor starts at the oldest retained entry;
        max_entries is 1..256."""
        raise NotImplementedError


class HolderClient(Holder):
    """Calls abstraction.credentials/holder@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def store(self, expected_revision: str, registration: Registration) -> StoreResult:
        _service_check("string", expected_revision)
        _service_check("Registration", registration)
        _args = _HolderStoreArguments()
        _args.expected_revision = expected_revision
        _args.registration = registration
        _arguments = _service_encode(_write_oa_holder_store_arguments, _args, 1)
        _service_decode(_read_oa_holder_store_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/holder@1", "Store", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/holder@1", "Store")
        _result = _service_decode(_read_oa_holder_store_result, _payload, 1)
        return _result.value

    def rotate(self, expected_revision: str, rotation: Rotation) -> RotateResult:
        _service_check("string", expected_revision)
        _service_check("Rotation", rotation)
        _args = _HolderRotateArguments()
        _args.expected_revision = expected_revision
        _args.rotation = rotation
        _arguments = _service_encode(_write_oa_holder_rotate_arguments, _args, 1)
        _service_decode(_read_oa_holder_rotate_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/holder@1", "Rotate", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/holder@1", "Rotate")
        _result = _service_decode(_read_oa_holder_rotate_result, _payload, 1)
        return _result.value

    def revoke(self, expected_revision: str, name: str) -> RevokeResult:
        _service_check("string", expected_revision)
        _service_check("string", name)
        _args = _HolderRevokeArguments()
        _args.expected_revision = expected_revision
        _args.name = name
        _arguments = _service_encode(_write_oa_holder_revoke_arguments, _args, 1)
        _service_decode(_read_oa_holder_revoke_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/holder@1", "Revoke", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/holder@1", "Revoke")
        _result = _service_decode(_read_oa_holder_revoke_result, _payload, 1)
        return _result.value

    def list(self, cursor: str, limit: int) -> MetadataPage:
        _service_check("string", cursor)
        _service_check("i64", limit)
        _args = _HolderListArguments()
        _args.cursor = cursor
        _args.limit = limit
        _arguments = _service_encode(_write_oa_holder_list_arguments, _args, 1)
        _service_decode(_read_oa_holder_list_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/holder@1", "List", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/holder@1", "List")
        _result = _service_decode(_read_oa_holder_list_result, _payload, 1)
        return _result.value

    def audit(self, cursor: str, max_entries: int) -> AuditPage:
        _service_check("string", cursor)
        _service_check("i64", max_entries)
        _args = _HolderAuditArguments()
        _args.cursor = cursor
        _args.max_entries = max_entries
        _arguments = _service_encode(_write_oa_holder_audit_arguments, _args, 1)
        _service_decode(_read_oa_holder_audit_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/holder@1", "Audit", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/holder@1", "Audit")
        _result = _service_decode(_read_oa_holder_audit_result, _payload, 1)
        return _result.value


class Applier:
    """Enforcer-only application of a named credential to one request. The
    receiving host designates the consuming services by program, as rights
    DecideFor designates enforcers; nil designation refuses every call. Headers
    cross this boundary to a designated service only, never to an application
    client, and never to a remote host. A remote provider holds its own applier
    and registrations; delegation carries the name. On platforms without process
    and path proof every Apply is forbidden."""

    def check(self, usage: Use) -> CheckResult:
        """Evaluate whether Apply would succeed for this use, for admission and
        adopter preflight. Same designation and policy as Apply; reads no
        secret; appends a checked or refused audit entry."""
        raise NotImplementedError

    def apply(self, usage: Use) -> ApplyResult:
        """Read the secret for one outgoing request. Only an explicitly designated
        enforcer program, bound by native Program proof, is accepted;
        same-account access alone is forbidden. The holder rechecks rights on
        every call and never caches a decision or a value across calls."""
        raise NotImplementedError


class ApplierClient(Applier):
    """Calls abstraction.credentials/applier@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def check(self, usage: Use) -> CheckResult:
        _service_check("Use", usage)
        _args = _ApplierCheckArguments()
        _args.usage = usage
        _arguments = _service_encode(_write_oa_applier_check_arguments, _args, 1)
        _service_decode(_read_oa_applier_check_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/applier@1", "Check", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/applier@1", "Check")
        _result = _service_decode(_read_oa_applier_check_result, _payload, 1)
        return _result.value

    def apply(self, usage: Use) -> ApplyResult:
        _service_check("Use", usage)
        _args = _ApplierApplyArguments()
        _args.usage = usage
        _arguments = _service_encode(_write_oa_applier_apply_arguments, _args, 1)
        _service_decode(_read_oa_applier_apply_arguments, _arguments, 1)
        _request = _service_request("abstraction.credentials/applier@1", "Apply", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.credentials/applier@1", "Apply")
        _result = _service_decode(_read_oa_applier_apply_result, _payload, 1)
        return _result.value
